// Package terminalfiles delivers files to the filesystem of a known terminal
// host. File bytes travel over a separate SSH channel, never through PTY input.
package terminalfiles

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/jordanhubbard/webmux/server/internal/session"
	"github.com/jordanhubbard/webmux/server/internal/storage"
	"github.com/jordanhubbard/webmux/server/internal/upload"
)

// The staged upload name is generated by upload.Service, never used as raw
// shell input. A private remote directory prevents overwrite and path guessing.
func remoteCommand(name string) (string, error) {
	if !regexp.MustCompile(`^[a-zA-Z0-9._-]{1,255}$`).MatchString(name) {
		return "", errors.New("invalid staged filename")
	}
	return `umask 077; d=$(mktemp -d /tmp/webmux-upload.XXXXXXXXXX) || exit 1; ` +
		`trap 'rm -f "$d/` + name + `"; rmdir "$d"' 1 2 3 15; ` +
		`if cat >"$d/` + name + `"; then printf '\nWEBMUX_FILE:%s\n' "$d/` + name + `"; else rm -f "$d/` + name + `"; rmdir "$d"; exit 1; fi`, nil
}

func Command(ctx context.Context, s session.Session, store *storage.Store, controlPath, filename string) (*exec.Cmd, error) {
	command, err := remoteCommand(filename)
	if err != nil {
		return nil, err
	}
	args := []string{"-T", "-o", "BatchMode=yes", "-o", "StrictHostKeyChecking=yes", "-o", "ConnectTimeout=8", "-o", "ClearAllForwardings=yes", "-o", "RemoteCommand=none", "-o", "RequestTTY=no", "-p", strconv.Itoa(s.Port)}
	if s.Port == 0 {
		args[len(args)-1] = "22"
	}
	if controlPath != "" {
		args = append(args, "-S", controlPath, "-o", "ControlMaster=no")
	}
	if s.KeyID != "" {
		var keys struct {
			Keys []struct {
				ID   string `yaml:"id"`
				Path string `yaml:"private_key_path"`
			} `yaml:"keys"`
		}
		if err := store.ReadConfig("keys.yaml", &keys); err != nil {
			return nil, err
		}
		found := false
		for _, key := range keys.Keys {
			if key.ID == s.KeyID {
				args = append(args, "-i", key.Path)
				found = true
				break
			}
		}
		if !found {
			return nil, errors.New("terminal SSH key is no longer configured")
		}
	}
	if s.Username != "" {
		args = append(args, "-l", s.Username)
	}
	args = append(args, "--", s.Hostname, command)
	return exec.CommandContext(ctx, "ssh", args...), nil
}

type limitedOutput struct {
	bytes.Buffer
	overflow bool
}

func (b *limitedOutput) Write(p []byte) (int, error) {
	n := len(p)
	remaining := 8192 - b.Len()
	if len(p) > remaining {
		p = p[:remaining]
		b.overflow = true
	}
	_, _ = b.Buffer.Write(p)
	return n, nil
}

func Deliver(ctx context.Context, s session.Session, store *storage.Store, controlPath string, staged upload.Result) (upload.Result, error) {
	if s.Transport == "local" || s.BrowserLocal || s.Agent() {
		return staged, nil
	}
	if s.Transport != "ssh" && s.Transport != "mosh" && s.Transport != "" {
		return upload.Result{}, errors.New("file transfer requires a local tmux or SSH terminal with a known host")
	}
	ctx, cancel := context.WithTimeout(ctx, 25*time.Second)
	defer cancel()
	cmd, err := Command(ctx, s, store, controlPath, staged.Name)
	if err != nil {
		return upload.Result{}, err
	}
	f, err := os.Open(staged.Path)
	if err != nil {
		return upload.Result{}, err
	}
	defer f.Close()
	cmd.Stdin = io.LimitReader(f, upload.MaxFileSize)
	var out limitedOutput
	cmd.Stdout = &out
	cmd.Stderr = io.Discard
	cmd.WaitDelay = time.Second
	if err := cmd.Run(); err != nil {
		if ctx.Err() != nil {
			return upload.Result{}, errors.New("file transfer timed out; reconnect the terminal and retry")
		}
		return upload.Result{}, errors.New("SSH file transfer failed. Reconnect to reuse its authenticated connection, or configure SSH key authentication. The remote host must provide a POSIX shell and mktemp")
	}
	if out.overflow {
		return upload.Result{}, errors.New("SSH returned excessive transfer output")
	}
	// Ignore login banners, but require exactly one valid absolute-path marker.
	var remote string
	for _, line := range strings.Split(out.String(), "\n") {
		if !strings.HasPrefix(line, "WEBMUX_FILE:") {
			continue
		}
		value := strings.TrimPrefix(line, "WEBMUX_FILE:")
		if remote != "" || !strings.HasPrefix(value, "/tmp/webmux-upload.") || strings.ContainsAny(value, "\r\x00") || filepath.Base(value) != staged.Name {
			return upload.Result{}, errors.New("SSH returned an invalid file destination")
		}
		remote = value
	}
	if remote == "" {
		return upload.Result{}, fmt.Errorf("SSH did not confirm file delivery")
	}
	return upload.Result{Path: remote, Name: staged.Name, Size: staged.Size}, nil
}
